<?php $title='Calendario'; require __DIR__.'/_top.php'; $prev=$start->modify('-1 month')->format('Y-m'); $next=$start->modify('+1 month')->format('Y-m'); ?><div class="page-heading"><div><p class="eyebrow">Ocupacao</p><h1>Calendario</h1></div><div class="month-nav"><a href="?mes=<?= $prev ?>">←</a><strong><?= ucfirst($start->format('m/Y')) ?></strong><a href="?mes=<?= $next ?>">→</a></div></div><section class="admin-panel calendar-panel"><div class="calendar-weekdays"><?php foreach(['Dom','Seg','Ter','Qua','Qui','Sex','Sab'] as $d): ?><span><?= $d ?></span><?php endforeach; ?></div><div class="month-grid"><?php $cursor=$start->modify('-'.$start->format('w').' days'); for($cell=0;$cell<42;$cell++,$cursor=$cursor->modify('+1 day')): $day=$cursor->format('Y-m-d'); ?><article class="calendar-day <?= $cursor->format('m')!==$start->format('m')?'outside':'' ?>"><strong><?= $cursor->format('d') ?></strong><?php foreach($events as $event): if($event['checkin']<=$day&&$event['checkout']>$day): ?><a class="calendar-event status-<?= strtolower($event['status']) ?>" href="<?= e(base_url('admin/reservas/'.$event['id'])) ?>" title="<?= e($event['nome_cliente'].' · '.$event['origem']) ?>"><?= e($event['codigo']) ?><small><?= e($event['nome_cliente']) ?> · <?= e($event['origem']) ?></small></a><?php endif; endforeach; ?><?php foreach($blocks as $block): if($block['data_inicio']<=$day&&$block['data_fim']>$day): ?><span class="calendar-event block" title="<?= e($block['motivo']) ?>"><?= e($block['origem']) ?><small><?= e($block['motivo']) ?></small></span><?php endif; endforeach; ?></article><?php endfor; ?></div></section><div class="detail-grid"><section class="admin-panel"><div class="panel-heading"><h2>Novo bloqueio manual</h2></div><form class="admin-form" action="<?= e(base_url('admin/bloqueios')) ?>" method="post"><?= csrf_field() ?><label>Inicio<input type="date" name="data_inicio" required></label><label>Fim (data liberada)<input type="date" name="data_fim" required></label><label>Tipo<select name="origem"><option value="USO_PROPRIO">Uso proprio</option><option value="MANUTENCAO">Manutencao</option><option value="RESERVA_EXTERNA">Reserva externa</option><option value="INDISPONIBILIDADE">Indisponibilidade</option><option value="OUTRO">Outro</option></select></label><label>Motivo<input name="motivo" maxlength="255" required></label><button class="admin-primary">Bloquear datas</button></form></section><section class="admin-panel"><div class="panel-heading"><h2>Bloqueios do mes</h2></div><?php foreach($blocks as $block): ?><div class="block-row"><div><strong><?= e($block['motivo']) ?></strong><small><?= date('d/m/Y',strtotime($block['data_inicio'])) ?>–<?= date('d/m/Y',strtotime($block['data_fim'])) ?> · <?= e($block['origem']) ?></small></div><?php if(!$block['reserva_id']): ?><form action="<?= e(base_url('admin/bloqueios/'.$block['id'].'/excluir')) ?>" method="post" data-confirm="Excluir este bloqueio?"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$block['id'] ?>"><button class="admin-danger">Excluir</button></form><?php endif; ?></div><?php endforeach; ?></section></div><?php require __DIR__.'/_bottom.php'; ?>
